head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil22100";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — realInvstgSubmitPermiYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil22100.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "registerBtn", fn: function(){ return ((dma_pageContext.get("realInvstgSubmitPermiYn") ?? "") === 'Y'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("endListPage")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil22100.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_list_oncellclick
 * @description grd_list 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_list_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_list');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_list */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.realInvstgDetail(r["bzProcsNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_list.oncellclick' });
    }
};

/**
 * @method
 * @name registerBtn_onclick
 * @description 「자료 제출」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerBtn_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil22100.registerBtn_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_49_onclick
 * @description krxpage_pagenavigator_49 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_49_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_loadListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_49.page' }); } await scwin.tx_load_list(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_realInvstgDetail
 * @description real Invstg Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_realInvstgDetail = async function () {
    const sbmOptions = {
        id: "tx_fn_realInvstgDetail",
        method: "post",
        action: "/company/realInvstg.do",
        ref: "dma_realInvstgDetailReq",
        target: "dlt_list=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_register
 * @description register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/company/realInvstg.do",
        ref: "dma_registerReq",
        target: "dlt_list=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/company/realInvstg.do",
        ref: "dma_searchListReq",
        target: "dlt_list=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/company/realInvstg.do?method=searchRealInvstgList",
        ref: "dma_loadListReq",
        target: "dlt_list=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_49").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name realInvstgDetail
 * @description real Invstg Detail 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.realInvstgDetail = async function (bzProcsNo) {
    const frm = (document.realInvstgDataForm || { elements: [] });
    $c.util.getComponent('ipt_method').setValue("searchRealInvstgDetail");
    $c.util.getComponent('ipt_bzProcsNo').setValue(bzProcsNo);
    // TODO Stage2(규칙 19): jQuery — 폼 제출 → $c.sbm 서브미션(규칙 6, B-4 제출 주소 회신)
    $('#realInvstgDataForm').attr("action", "realInvstg.do");
    await scwin.tx_fn_realInvstgDetail();
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const frm = (document.realInvstgDataForm || { elements: [] });
    $c.util.getComponent('ipt_method').setValue("registerRealInvstg");
    frm.action = 'realInvstg.do';
    await scwin.tx_fn_register();
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    if (dma_hiddenStore.get("startDate") > dma_hiddenStore.get("endDate")) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    const frm = (document.realInvstgDataForm || { elements: [] });
    $c.util.getComponent('ipt_method').setValue("searchRealInvstgList");
    // TODO Stage2(규칙 19): jQuery — 폼 제출 → $c.sbm 서브미션(규칙 6, B-4 제출 주소 회신)
    $('#realInvstgDataForm').attr("action", "realInvstg.do");
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name al
 * @description al 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.al = async function () {
    await $c.win.alert($, {  });
};
